function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // brain
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // thought bubble
  ctx.beginPath();
  ctx.arc(W/2 + 80 + 20 * Math.sin(t), H/2 - 20 + 10 * Math.cos(t), 20, 0, 2 * Math.PI);
  ctx.stroke();

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 100, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 120);
  ctx.lineTo(W/2, H/2 + 200);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 150);
  ctx.lineTo(W/2 - 30, H/2 + 180);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 150);
  ctx.lineTo(W/2 + 30, H/2 + 180);
  ctx.stroke();

  // eyes
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 5, H/2 + 90, 2, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 5, H/2 + 90, 2, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
